import{_ as s,o as a,c as n,a8 as o}from"./chunks/framework.CAT8sTE0.js";const c=JSON.parse('{"title":"数据分布场景与锁设计（单库 / 主从 / 分片 / 分布式库）","description":"","frontmatter":{"title":"数据分布场景与锁设计（单库 / 主从 / 分片 / 分布式库）","date":"2026-11-06T00:00:00.000Z"},"headers":[],"relativePath":"service/common/data-distribution-locks.md","filePath":"service/common/data-distribution-locks.md"}'),d={name:"service/common/data-distribution-locks.md"};function r(e,t,i,p,l,h){return a(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="数据分布场景与锁设计-单库-主从-分片-分布式库" tabindex="-1">数据分布场景与锁设计（单库 / 主从 / 分片 / 分布式库） <a class="header-anchor" href="#数据分布场景与锁设计-单库-主从-分片-分布式库" aria-label="Permalink to &quot;数据分布场景与锁设计（单库 / 主从 / 分片 / 分布式库）&quot;">​</a></h1><blockquote><p>本质一句话：<strong>数据怎么摆，决定了锁在哪生效</strong>。单库靠 DB 行锁、主从靠复制策略、分片靠分片键让锁局部化、分布式库靠底层封装——<strong>四个场景，四套完全不同的&quot;一致性武器&quot;</strong>。</p></blockquote><p><strong>优先级 P1</strong>：面试与架构里最容易被绕晕的一组概念：多实例、主从、分库分表、分布式数据库——它们的数据存放方式不同，&quot;锁 / 一致 / 并发&quot;的问题也完全不同。</p><div class="tip custom-block"><p class="custom-block-title">这篇的定位</p><p>这篇是<strong>一张地图 + 一条主线</strong>，不是每个方案的实现细节。目的是让你在面试和架构评审里<strong>不被绕进去</strong>：别人说&quot;我们上了分库分表&quot;，你能立刻说出&quot;那你们的跨片事务怎么办&quot;。</p><p>四个形态的实现细节分别见：<a href="/knowledge/service/common/mysql-advanced.html">MySQL 进阶</a>（主从）、<a href="/knowledge/service/common/distributed-basics.html">分布式基础</a>（CAP、分布式事务、分布式 ID）、<a href="/knowledge/service/common/concurrency-locks.html">并发锁应用</a>（锁本身）。</p></div><h2 id="_0-全景-三分钟看懂这篇" tabindex="-1">0. 全景：三分钟看懂这篇 <a class="header-anchor" href="#_0-全景-三分钟看懂这篇" aria-label="Permalink to &quot;0. 全景：三分钟看懂这篇&quot;">​</a></h2><blockquote><p>难度：了解</p></blockquote><p><strong>先看地基——四种形态的区别只有一句话</strong>：<strong>数据是&quot;切&quot;还是&quot;复制&quot;</strong>。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph ①[&quot;单库（多实例共享）&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A1[&quot;一份数据&quot;] --&gt; A2[&quot;所有实例连同一个 MySQL&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph ②[&quot;主从 / 读写分离&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B1[&quot;同一份数据 · 多副本&quot;] --&gt; B2[&quot;主库写 · 从库读&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph ③[&quot;分库分表&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C1[&quot;不同数据 · 切片&quot;] --&gt; C2[&quot;每个库存一部分&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph ④[&quot;分布式数据库（TiDB）&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        D1[&quot;切片 + 每片多副本&quot;] --&gt; D2[&quot;对外像单个 MySQL&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style A2 fill:#dcfce7,stroke:#22c55e</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style B2 fill:#fef3c7,stroke:#f59e0b</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style C2 fill:#fef3c7,stroke:#f59e0b</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style D2 fill:#dbeafe,stroke:#3b82f6</span></span></code></pre></div><p><strong>最容易混的两个</strong>（面试高频）：</p><ul><li>② <strong>主从 = 同一份数据多副本</strong>（每台都是全量）</li><li>③ <strong>分库 = 不同数据分散</strong>（每台存一部分）</li></ul><table tabindex="0"><thead><tr><th>形态</th><th>数据是&quot;切&quot;还是&quot;复制&quot;</th><th>一致性</th><th>扩展方向</th></tr></thead><tbody><tr><td>① 单库</td><td>一份</td><td>强一致（DB 保证）</td><td>加应用实例（水平）</td></tr><tr><td>② 主从</td><td><strong>复制</strong>（全量副本）</td><td>最终一致（异步复制）</td><td><strong>读</strong>扩展</td></tr><tr><td>③ 分片</td><td><strong>切分</strong>（各存部分）</td><td>各片独立（跨片要分布式事务）</td><td>写 + 读扩展</td></tr><tr><td>④ TiDB</td><td>切分 + 副本</td><td>底层封装（对外像单库）</td><td>自动扩展</td></tr></tbody></table><p><strong>贯穿全文的主线</strong>（先记住这句，细节后面都能挂上去）：</p><blockquote><p><strong>能局部锁就别跨节点。</strong></p></blockquote><p><strong>分五块</strong>：</p><table tabindex="0"><thead><tr><th>块</th><th>内容</th><th>读到什么程度</th></tr></thead><tbody><tr><td>1 用途</td><td>什么时候需要从①走向②③④</td><td>能做演进决策</td></tr><tr><td>2 最小可用</td><td>一条 SQL 在四种形态下分别意味着什么</td><td>能画出来</td></tr><tr><td>3 用法</td><td>四种形态各自的&quot;一致性武器&quot;</td><td>知道每个场景靠什么保一致</td></tr><tr><td>4 原理</td><td>为什么主从的一致不靠锁</td><td>能解释设计取舍</td></tr><tr><td>5 边界与坑</td><td>各形态的典型事故</td><td>能对上号</td></tr></tbody></table><p><strong>学完你能</strong>：① 一句话说清主从和分片的区别；② 解释&quot;写完立刻读不到自己写的数据&quot;是复制延迟不是锁问题；③ 说出分片键设计的最高优先级；④ 听到&quot;我们上了 TiDB&quot;能问出对的问题。</p><p><strong>本篇讲什么、不讲什么</strong>：</p><table tabindex="0"><thead><tr><th>知识点</th><th>档位</th><th>处理</th></tr></thead><tbody><tr><td>四种形态的区分</td><td>核心</td><td>正文 0、2</td></tr><tr><td>单库场景的锁设计</td><td>核心</td><td>正文 3.1</td></tr><tr><td>主从的复制延迟与路由策略</td><td>核心</td><td>正文 3.2</td></tr><tr><td>分片键设计与配套问题</td><td>核心</td><td>正文 3.3</td></tr><tr><td>分布式数据库的定位</td><td>进阶</td><td>正文 3.4</td></tr><tr><td>演进决策（何时该上什么）</td><td>进阶</td><td>正文 1.2</td></tr><tr><td>具体实现（中间件配置、分片算法）</td><td>—</td><td>不写，用到再查</td></tr><tr><td>分布式事务的四种方案</td><td>—</td><td>见 <a href="/knowledge/service/common/distributed-basics.html">分布式基础</a></td></tr></tbody></table><hr><h2 id="_1-用途-什么时候会走到这些形态" tabindex="-1">1. 用途：什么时候会走到这些形态 <a class="header-anchor" href="#_1-用途-什么时候会走到这些形态" aria-label="Permalink to &quot;1. 用途：什么时候会走到这些形态&quot;">​</a></h2><blockquote><p>难度：了解</p></blockquote><h3 id="_1-1-演进触发点" tabindex="-1">1.1 演进触发点 <a class="header-anchor" href="#_1-1-演进触发点" aria-label="Permalink to &quot;1.1 演进触发点&quot;">​</a></h3><p><strong>不是&quot;数据大了就分片&quot;，是每种形态解决一个特定瓶颈</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 单库</span></span>
<span class="line"><span>   瓶颈：应用实例多了 → 数据库连接数不够 → 加应用实例（水平扩展）</span></span>
<span class="line"><span>   ↓ 读流量压垮单库</span></span>
<span class="line"><span>② 主从（读写分离）</span></span>
<span class="line"><span>   瓶颈：写还是单点 → 但读已经扩展不动了</span></span>
<span class="line"><span>   ↓ 单表真的到亿级</span></span>
<span class="line"><span>③ 分库分表</span></span>
<span class="line"><span>   瓶颈：写扩展 + 单表索引效率</span></span>
<span class="line"><span>   ↓ 不想自己搞分片、跨片事务、分布式 ID</span></span>
<span class="line"><span>④ 分布式数据库（TiDB / CockroachDB）</span></span></code></pre></div><p><strong>每一步都是&quot;用新复杂度换旧瓶颈&quot;</strong>，所以<strong>不该跳级</strong>——单库能扛的就不上主从，主从能扛的就不分片。</p><h3 id="_1-2-什么时候该考虑从1往上走" tabindex="-1">1.2 什么时候该考虑从①往上走 <a class="header-anchor" href="#_1-2-什么时候该考虑从1往上走" aria-label="Permalink to &quot;1.2 什么时候该考虑从①往上走&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>目标形态</th><th>先做什么</th></tr></thead><tbody><tr><td>读 QPS 压顶，<strong>写还不高</strong></td><td>② 主从</td><td>加从库 + 读写路由</td></tr><tr><td>单表索引变慢（千万级）</td><td>③ 分片（按业务维度）</td><td>先优化索引和慢查询</td></tr><tr><td>写 QPS 压顶（单机写不动）</td><td>③ 分片 / ④ 分布式库</td><td>先做库表拆分设计</td></tr><tr><td><strong>运维能力不足</strong></td><td>停在 ① 或 ②</td><td>别上③④，TiDB 集群本身也要人管</td></tr></tbody></table><p><strong>最后一行很重要</strong>：分布式数据库不是&quot;更简单的数据库&quot;，它是<strong>把复杂度从你转移到运维团队</strong>的产品。没有能人管 TiDB 集群的团队，上 TiDB 只是把数据库问题换成集群问题。</p><hr><h2 id="_2-最小可用-一条-sql-在四种形态下" tabindex="-1">2. 最小可用：一条 SQL 在四种形态下 <a class="header-anchor" href="#_2-最小可用-一条-sql-在四种形态下" aria-label="Permalink to &quot;2. 最小可用：一条 SQL 在四种形态下&quot;">​</a></h2><blockquote><p>难度：了解</p></blockquote><p><strong>场景</strong>：扣减商品库存，防止超卖。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><strong>同一条 SQL，四种形态下含义完全不同</strong>：</p><table tabindex="0"><thead><tr><th>形态</th><th>这条 SQL 打在哪个库</th><th>谁能同时执行</th><th>一致性靠什么</th></tr></thead><tbody><tr><td><strong>① 单库</strong></td><td>主库（唯一）</td><td>所有实例的这条 SQL → <strong>DB 行锁串行</strong></td><td>DB 行锁 + 事务</td></tr><tr><td><strong>② 主从</strong></td><td><strong>必须是主库</strong></td><td>同上（写都在主库）</td><td>主库行锁 + <strong>复制策略</strong>（读从库有延迟）</td></tr><tr><td><strong>③ 分片</strong></td><td><code>sku_id</code> 哈希到的那个分片</td><td>只有<strong>同一个分片</strong>内的请求会互斥</td><td>片内行锁；跨片要分布式事务</td></tr><tr><td><strong>④ TiDB</strong></td><td>逻辑上&quot;一个库&quot;</td><td>全局由存储层协调</td><td>内部 Region + Raft，<strong>对应用透明</strong></td></tr></tbody></table><p><strong>三个立刻能得出的结论</strong>：</p><ol><li><strong>② 主从下，写操作必须走主库</strong>——写到从库就废了（从库是只读副本）。</li><li><strong>③ 分片下，&quot;防超卖&quot;只在分片内成立</strong>——如果库存和订单在不同分片，&quot;扣库存 + 建订单&quot;就是跨片事务。</li><li><strong>④ TiDB 下这条 SQL 不用改</strong>——它对外就是一个 MySQL 兼容库。</li></ol><blockquote><p><strong>自检</strong>：分库分表后，<code>UPDATE stock ... WHERE sku_id = 100</code> 这条 SQL 的执行范围是什么？多个应用实例同时下同一单会怎样？</p></blockquote><details class="details custom-block"><summary>参考答案</summary><p><strong>执行范围</strong>：只落在 <code>sku_id=100</code> 哈希到的<strong>那一个分片</strong>（假设按 sku_id 分片）。其他分片完全不参与。</p><p><strong>多实例同时下同一单</strong>：</p><ul><li><strong>同一个 sku_id</strong> → 同一个分片 → <strong>分片内的 DB 行锁</strong>（或 MVCC 下的原子更新）保证串行 → <code>AND stock &gt; 0</code> 这个条件让只有一个请求成功，<strong>不会超卖</strong>。这和单库完全一样。</li><li><strong>不同 sku_id</strong> → 不同分片 → 各走各的，<strong>天然并行</strong>，互不阻塞。</li></ul><p>所以&quot;分片后锁还有效吗&quot;这个问题，答案是：<strong>对同一分片的数据有效（局部锁），对跨分片的数据无效（要分布式事务）</strong>。</p><p><strong>这正是分片键设计的意义</strong>：让需要互斥的数据落在同一片。如果库存按 sku_id 分片、订单按 order_id 分片，那&quot;扣库存 + 建订单&quot;就跨片了，每次下单都要走分布式事务——代价极高。</p></details><hr><h2 id="_3-用法-四种形态各自的-一致性武器" tabindex="-1">3. 用法：四种形态各自的&quot;一致性武器&quot; <a class="header-anchor" href="#_3-用法-四种形态各自的-一致性武器" aria-label="Permalink to &quot;3. 用法：四种形态各自的&quot;一致性武器&quot;&quot;">​</a></h2><blockquote><p>难度：会用</p></blockquote><h3 id="_3-1-场景1-多应用实例-单库" tabindex="-1">3.1 场景①：多应用实例 + 单库 <a class="header-anchor" href="#_3-1-场景1-多应用实例-单库" aria-label="Permalink to &quot;3.1 场景①：多应用实例 + 单库&quot;">​</a></h3><p><strong>数据</strong>：一份，所有实例连同一个 MySQL。</p><p><strong>锁设计分两类，不要混</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据行 → DB 行锁（自动，跨实例）</span></span>
<span class="line"><span>代码段 → Redis 锁（自己加，跨实例）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>要互斥的东西</th><th>用什么</th><th>为什么</th></tr></thead><tbody><tr><td><strong>数据行</strong>（同一行的更新）</td><td><strong>DB 行锁 / 乐观锁 / 原子 SQL</strong></td><td>共享同一个 DB，行锁<strong>天然跨实例</strong>——不管你部署几个应用实例都有效</td></tr><tr><td><strong>与数据行无关的逻辑</strong>（定时任务只跑一次、同一用户只能发一封邮件）</td><td><strong>Redis 锁</strong></td><td>DB 管不了&quot;代码段互斥&quot;，只能自己加锁</td></tr></tbody></table><p><strong>核心认知</strong>：应用再多实例，只要共享 DB，<strong>数据一致就靠 DB</strong>；Redis 锁只补&quot;代码互斥&quot;这块。<strong>能用 DB 约束解决的，别用 Redis 锁</strong>（唯一索引比分布式锁可靠，见 <a href="/knowledge/service/common/redis-intro.html">Redis 入门 · 分布式锁的边界</a>）。</p><h3 id="_3-2-场景2-主从-读写分离" tabindex="-1">3.2 场景②：主从 / 读写分离 <a class="header-anchor" href="#_3-2-场景2-主从-读写分离" aria-label="Permalink to &quot;3.2 场景②：主从 / 读写分离&quot;">​</a></h3><p><strong>架构</strong>：主库写、从库读，主库把 binlog <strong>异步</strong>复制给从库。<strong>主从 = 同一份数据的多个全量副本。</strong></p><p><strong>它解决什么</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读并发大 → 加从库（每台分担一部分读流量）→ 读水平扩展 ✓</span></span>
<span class="line"><span>写并发   → 瓶颈仍在主库（单点写）→ 主从不解决写扩展 ✗</span></span></code></pre></div><p><strong>写一致性仍然在主库</strong>：所有写都走主库，主库的行锁和单库场景一样管并发写——<strong>从库只读，没有写并发问题</strong>。</p><p><strong>真正的难点：复制延迟</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户下单 → 写主库成功 → 跳转订单页 → 读的是从库</span></span>
<span class="line"><span>         → 从库可能还没复制到 → &quot;订单不存在&quot;？</span></span></code></pre></div><p><strong>主从是&quot;最终一致&quot;</strong>：从库迟早追上，但追上之前的窗口内读到的是旧数据。</p><p><strong>解决策略（不是加锁！是复制与路由策略）</strong>：</p><table tabindex="0"><thead><tr><th>手段</th><th>做法</th><th>解决</th></tr></thead><tbody><tr><td><strong>半同步复制</strong></td><td>写主库时<strong>等至少一个从库 ACK 才返回成功</strong></td><td>缩小延迟窗口（从&quot;毫秒级不确定&quot;到&quot;至少一个从库确认&quot;）</td></tr><tr><td><strong>关键读走主库</strong></td><td>刚写过的数据（自己的订单）路由到主库读</td><td>避免&quot;写后读不到自己写的数据&quot;</td></tr><tr><td><strong>读从库容忍延迟</strong></td><td>报表/列表这类可接受最终一致的读从库</td><td>榨干从库读能力</td></tr><tr><td><strong>复制延迟监控</strong></td><td>监控主从落后秒数，超阈值告警或切主读</td><td>别让延迟悄悄放大</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写 → 主库（行锁保证写一致）→ 半同步等从库确认 → 返回成功</span></span>
<span class="line"><span>读关键数据 → 主库（要读到刚写的）</span></span>
<span class="line"><span>读可容忍数据 → 从库（可能旧几毫秒/秒，最终一致）</span></span></code></pre></div><p><strong>主从切换的坑</strong>：主库宕机切从库时，可能丢&quot;还没复制过去的写&quot;——半同步 + GTID 可减少损失。<strong>主从是容灾 + 读扩展方案，不是数据零丢失方案</strong>（强零丢失得靠同步复制或分布式 DB）。</p><h3 id="_3-3-场景3-分库分表-数据切片" tabindex="-1">3.3 场景③：分库分表（数据切片） <a class="header-anchor" href="#_3-3-场景3-分库分表-数据切片" aria-label="Permalink to &quot;3.3 场景③：分库分表（数据切片）&quot;">​</a></h3><p><strong>数据</strong>：按<strong>分片键</strong>（如 user_id、order_id）切到多个库，每库只存一部分。</p><p><strong>锁设计核心：让锁&quot;局部化&quot;</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同一条数据 → 只在一个分片里 → 行锁在该分片自动生效（和单库一样）</span></span>
<span class="line"><span>跨分片的操作 → 一次改多个库的数据 → 需要分布式事务（代价大）</span></span></code></pre></div><p><strong>所以分片键设计是最高优先级的&quot;锁设计&quot;</strong>——让需要一起操作的数据落在同一分片：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ 订单按 user_id 分片，但&quot;订单 + 订单明细 + 扣库存&quot;散在不同片 → 跨片事务</span></span>
<span class="line"><span>✅ 让&quot;一个订单的聚合&quot;同片 → 单分片内行锁局部有效，无需跨库协调</span></span></code></pre></div><p><strong>分片后的配套问题</strong>：</p><table tabindex="0"><thead><tr><th>问题</th><th>方案</th></tr></thead><tbody><tr><td>自增主键失效（各片独立自增会撞）</td><td><strong>分布式 ID</strong>（雪花：时间戳+机器+序列号）</td></tr><tr><td>跨分片事务</td><td>分布式事务（2PC / TCC / Saga，<strong>能避免就避免</strong>）</td></tr><tr><td>跨库无唯一约束</td><td>幂等表 / 幂等状态机</td></tr><tr><td>热点分片（某 key 特别热）</td><td>拆 key（加后缀分散）/ 本地缓存</td></tr><tr><td>跨片查询（分页、聚合）</td><td>慢；要么改数据模型让查询单片，要么做二次查询 + 应用层聚合</td></tr></tbody></table><p><strong>判断准则</strong>：<strong>能局部锁就别跨节点</strong>——分片键设计的目标是让 <strong>90% 的操作落在单片内</strong>（用局部行锁），只有极少数跨片才付分布式事务的代价。</p><p><strong>分片键的四个要求</strong>（设计时的检查清单）：</p><table tabindex="0"><thead><tr><th>要求</th><th>原因</th></tr></thead><tbody><tr><td><strong>数据要均匀</strong></td><td>否则热点分片（某个大客户 / 某个爆款 key）压垮一片</td></tr><tr><td><strong>查询要集中</strong></td><td>常用查询条件要能带上分片键，否则每次都跨片</td></tr><tr><td><strong>事务要内聚</strong></td><td>一个事务要改的数据必须在同一片</td></tr><tr><td><strong>要稳定</strong></td><td>分片键不能变（用户 ID 不能变；用自增 ID 的话，扩容时按 ID 取模会错位）</td></tr></tbody></table><h3 id="_3-4-场景4-分布式数据库-tidb-cockroachdb" tabindex="-1">3.4 场景④：分布式数据库（TiDB / CockroachDB） <a class="header-anchor" href="#_3-4-场景4-分布式数据库-tidb-cockroachdb" aria-label="Permalink to &quot;3.4 场景④：分布式数据库（TiDB / CockroachDB）&quot;">​</a></h3><p><strong>本质</strong>：分片（Region）+ 每片多副本（Raft 共识）+ 分布式事务（TiDB 用 Percolator 模型）——<strong>全部封装在存储层</strong>，对外是一个 MySQL 兼容的库。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你写：UPDATE stock SET stock=stock-1 WHERE id=1</span></span>
<span class="line"><span>底层：找到 id 所在 Region → 多副本 Raft 达成一致 → 行锁/MVCC 内部协调</span></span></code></pre></div><p><strong>对应用透明</strong>：行锁、事务隔离级别和单库一样，<strong>不需要你设计锁 / 分片 / 副本</strong>——数据库全包了。</p><p><strong>代价</strong>：</p><ul><li><strong>运维复杂度</strong>：TiDB 集群本身要人管（PD、TiKV、TiDB 三种角色）</li><li><strong>强一致写有跨节点协调开销</strong>：比单机自增慢（但比你自己搞分片简单得多）</li><li><strong>SQL 能力有边界</strong>：某些 MySQL 语法和 DDL 不完全兼容</li></ul><p><strong>适用</strong>：<strong>单库扛不住又不愿自己搞分库分表的团队</strong>。</p><hr><h2 id="_4-原理-为什么主从的一致不靠锁" tabindex="-1">4. 原理：为什么主从的一致不靠锁 <a class="header-anchor" href="#_4-原理-为什么主从的一致不靠锁" aria-label="Permalink to &quot;4. 原理：为什么主从的一致不靠锁&quot;">​</a></h2><blockquote><p>难度：懂原理</p></blockquote><p>这是本篇<strong>最值得记住的一条思维差异</strong>。</p><h3 id="_4-1-单库场景-一致性-锁的问题" tabindex="-1">4.1 单库场景：一致性 = 锁的问题 <a class="header-anchor" href="#_4-1-单库场景-一致性-锁的问题" aria-label="Permalink to &quot;4.1 单库场景：一致性 = 锁的问题&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>多个实例同时改同一行</span></span>
<span class="line"><span>  → 都打到同一个 DB</span></span>
<span class="line"><span>    → DB 的行锁把它们串行化</span></span>
<span class="line"><span>      → 一致</span></span></code></pre></div><p><strong>这里的风险是&quot;并发写冲突&quot;</strong>，所以用锁解决。</p><h3 id="_4-2-主从场景-一致性-时序的问题" tabindex="-1">4.2 主从场景：一致性 = 时序的问题 <a class="header-anchor" href="#_4-2-主从场景-一致性-时序的问题" aria-label="Permalink to &quot;4.2 主从场景：一致性 = 时序的问题&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>多个实例同时改同一行</span></span>
<span class="line"><span>  → 都打到主库</span></span>
<span class="line"><span>    → 主库行锁串行化 ✓（并发写没问题）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>但读的时候：</span></span>
<span class="line"><span>  → 读请求打到从库</span></span>
<span class="line"><span>    → 从库还没收到 binlog → 读到旧值 ❌</span></span></code></pre></div><p><strong>这里的风险不是&quot;并发写冲突&quot;，而是&quot;读到的数据比写的旧&quot;</strong>——是<strong>时序问题</strong>，不是并发问题。</p><p><strong>所以加锁解决不了它</strong>。锁能保证&quot;写是串行的&quot;，但保证不了&quot;从库已经追上主库&quot;。<strong>唯一的武器是复制策略</strong>：</p><table tabindex="0"><thead><tr><th>策略</th><th>怎么解决时序问题</th></tr></thead><tbody><tr><td>半同步复制</td><td>让主库<strong>等</strong>从库确认 → 把&quot;不确定的延迟窗口&quot;变成&quot;确定的最小延迟&quot;</td></tr><tr><td>读写路由</td><td>让关键读走主库 → <strong>绕开</strong>延迟窗口</td></tr><tr><td>延迟监控</td><td>知道窗口有多大 → 超阈值就切主读</td></tr></tbody></table><p><strong>一句话</strong>：<strong>单库靠锁，主从靠复制策略。</strong> 把这两套东西混了，就会得出&quot;给读请求加个分布式锁&quot;这种荒谬结论。</p><h3 id="_4-3-分片场景-一致性-局部性问题" tabindex="-1">4.3 分片场景：一致性 = 局部性问题 <a class="header-anchor" href="#_4-3-分片场景-一致性-局部性问题" aria-label="Permalink to &quot;4.3 分片场景：一致性 = 局部性问题&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同分片的数据 → 行锁有效（和单库一样）</span></span>
<span class="line"><span>跨分片的数据 → 需要协调（分布式事务）</span></span></code></pre></div><p><strong>所以分片键设计是最高优先级</strong>——它决定了 90% 的操作能不能用上&quot;局部行锁&quot;这个免费的武器。</p><h3 id="_4-4-分布式库-一致性-存储层的事" tabindex="-1">4.4 分布式库：一致性 = 存储层的事 <a class="header-anchor" href="#_4-4-分布式库-一致性-存储层的事" aria-label="Permalink to &quot;4.4 分布式库：一致性 = 存储层的事&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你写一条普通 SQL</span></span>
<span class="line"><span>  → 存储层找到数据所在 Region</span></span>
<span class="line"><span>    → 该 Region 的多个副本用 Raft 达成一致</span></span>
<span class="line"><span>      → 对外表现为&quot;一个普通的 MySQL 事务&quot;</span></span></code></pre></div><p><strong>应用层什么都不用设计</strong>——代价是这套机制本身很重（每条写都要跨节点共识）。</p><h3 id="_4-5-四种形态的统一视角" tabindex="-1">4.5 四种形态的统一视角 <a class="header-anchor" href="#_4-5-四种形态的统一视角" aria-label="Permalink to &quot;4.5 四种形态的统一视角&quot;">​</a></h3><table tabindex="0"><thead><tr><th>形态</th><th>一致性的<strong>风险来源</strong></th><th>对应的武器</th></tr></thead><tbody><tr><td>① 单库</td><td>并发写冲突</td><td><strong>DB 行锁</strong></td></tr><tr><td>② 主从</td><td><strong>复制延迟</strong>（时序）</td><td><strong>复制策略</strong>（不是锁！）</td></tr><tr><td>③ 分片</td><td><strong>跨片协调</strong></td><td><strong>分片键</strong>（让锁局部化）</td></tr><tr><td>④ 分布式库</td><td>节点间共识</td><td><strong>存储层封装</strong></td></tr></tbody></table><hr><h2 id="_5-边界与坑" tabindex="-1">5. 边界与坑 <a class="header-anchor" href="#_5-边界与坑" aria-label="Permalink to &quot;5. 边界与坑&quot;">​</a></h2><blockquote><p>难度：会用 + 懂原理</p></blockquote><h3 id="_5-1-一张表先过一遍" tabindex="-1">5.1 一张表先过一遍 <a class="header-anchor" href="#_5-1-一张表先过一遍" aria-label="Permalink to &quot;5.1 一张表先过一遍&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>见</th></tr></thead><tbody><tr><td>写完立刻查，查不到自己写的数据</td><td>5.2</td></tr><tr><td>加了从库但读流量没降</td><td>5.3</td></tr><tr><td>分片后某个接口特别慢</td><td>5.4</td></tr><tr><td>分片扩容后数据&quot;错位&quot;了</td><td>5.5</td></tr><tr><td>主从切换后丢了数据</td><td>5.6</td></tr><tr><td>说&quot;我们上了分布式库&quot;但说不清代价</td><td>5.7</td></tr></tbody></table><h3 id="_5-2-写完立刻读不到自己写的数据" tabindex="-1">5.2 写完立刻读不到自己写的数据 <a class="header-anchor" href="#_5-2-写完立刻读不到自己写的数据" aria-label="Permalink to &quot;5.2 写完立刻读不到自己写的数据&quot;">​</a></h3><p><strong>症状</strong>：下单成功，跳转订单页显示&quot;订单不存在&quot;。</p><p><strong>原因</strong>：<strong>复制延迟</strong>（4.2）——写主库成功就返回了，从库还没复制到。</p><p><strong>解法</strong>（按场景选）：</p><table tabindex="0"><thead><tr><th>场景</th><th>解法</th></tr></thead><tbody><tr><td>用户读自己的数据（订单详情）</td><td><strong>关键读走主库</strong>（按用户 ID 路由到主库）</td></tr><tr><td>列表/报表类读</td><td>容忍延迟，读从库</td></tr><tr><td>延迟已经很大</td><td>开半同步复制；检查是否有大事务 / 大批量操作卡住复制</td></tr><tr><td>写后必须立刻读</td><td><strong>别用主从</strong>，用单库或分布式数据库的强一致读</td></tr></tbody></table><p><strong>排查顺序</strong>：先确认是不是读走了从库（看日志/链路里连的是哪个实例）→ 再看主从延迟秒数（<code>SHOW SLAVE STATUS</code> 的 <code>Seconds_Behind_Master</code>）→ 延迟正常但仍读不到 → 检查路由规则。</p><h3 id="_5-3-加了从库但读流量没降" tabindex="-1">5.3 加了从库但读流量没降 <a class="header-anchor" href="#_5-3-加了从库但读流量没降" aria-label="Permalink to &quot;5.3 加了从库但读流量没降&quot;">​</a></h3><p><strong>症状</strong>：加了两台从库，流量还是全打主库。</p><p><strong>原因与对策</strong>：</p><table tabindex="0"><thead><tr><th>原因</th><th>解法</th></tr></thead><tbody><tr><td><strong>读路由没配</strong>（还是全走主库）</td><td>配读写分离（ShardingSphere / ProxySQL / 应用层自己路由）</td></tr><tr><td><strong>写后马上查的比例高</strong></td><td>关键读走主库是合理的，但要看比例</td></tr><tr><td><strong>从库延迟太高</strong>，被自动摘除</td><td>查复制延迟；解决后再挂回</td></tr><tr><td><strong>业务代码里直连了主库</strong>（硬编码数据源）</td><td>改数据源路由</td></tr></tbody></table><h3 id="_5-4-分片后某个接口特别慢" tabindex="-1">5.4 分片后某个接口特别慢 <a class="header-anchor" href="#_5-4-分片后某个接口特别慢" aria-label="Permalink to &quot;5.4 分片后某个接口特别慢&quot;">​</a></h3><p><strong>症状</strong>：大部分接口正常，某个列表接口从 50ms 变成 5s。</p><p><strong>原因</strong>：<strong>跨片查询</strong>。比如分页要按 <code>create_time</code> 排序，而分片键是 <code>user_id</code> → 每个分片都要取一部分再归并排序 → N 个分片 × 排序 → 慢。</p><p><strong>解法</strong>（按优先级）：</p><table tabindex="0"><thead><tr><th>方案</th><th>说明</th></tr></thead><tbody><tr><td><strong>改数据模型</strong></td><td>加冗余字段（如&quot;用户最近 N 条订单&quot;单独存一张表）</td></tr><tr><td><strong>改分片键</strong></td><td>让这个查询能带上分片键（代价大，慎重）</td></tr><tr><td><strong>应用层归并</strong></td><td>各分片查一部分 → 应用层合并排序（数据量大时仍慢，且有深分页问题）</td></tr><tr><td><strong>换成 ES</strong></td><td>搜索类查询交给搜索层</td></tr></tbody></table><p><strong>根本教训</strong>：<strong>分片键决定了哪些查询会慢</strong>。设计分片键时，必须拿实际的查询列表去套一遍——&quot;这个查询能带上分片键吗&quot;。</p><h3 id="_5-5-分片扩容后数据-错位" tabindex="-1">5.5 分片扩容后数据&quot;错位&quot; <a class="header-anchor" href="#_5-5-分片扩容后数据-错位" aria-label="Permalink to &quot;5.5 分片扩容后数据&quot;错位&quot;&quot;">​</a></h3><p><strong>症状</strong>：分片从 2 个扩到 4 个后，一半的数据查不到了。</p><p><strong>原因</strong>：<strong>取模分片的经典问题</strong>——<code>hash(key) % N</code>，N 从 2 变 4 → <strong>几乎所有 key 的归属都变了</strong>。</p><p><strong>解法</strong>：</p><table tabindex="0"><thead><tr><th>方案</th><th>说明</th></tr></thead><tbody><tr><td><strong>一致性哈希</strong>（+ 虚拟节点）</td><td>节点增减只影响少量 key（见 <a href="/knowledge/service/common/distributed-basics.html">分布式基础</a>）</td></tr><tr><td><strong>按范围分片</strong>（比如按 ID 区间）</td><td>扩容是&quot;新增一个区间&quot;，老数据不动</td></tr><tr><td><strong>预分片</strong>（一开始就分 1024 个逻辑分片，物理上按需分配）</td><td>扩容只是把逻辑分片挪到新机器，<strong>映射不变</strong></td></tr><tr><td><strong>双写迁移</strong></td><td>扩容期间新旧路由同时写、逐步搬数据（最重但最通用）</td></tr></tbody></table><p><strong>这是分库分表最不可逆的决策</strong>——分片键和分片算法定了，改起来要停机搬数据。</p><h3 id="_5-6-主从切换后丢了数据" tabindex="-1">5.6 主从切换后丢了数据 <a class="header-anchor" href="#_5-6-主从切换后丢了数据" aria-label="Permalink to &quot;5.6 主从切换后丢了数据&quot;">​</a></h3><p><strong>症状</strong>：主库宕机切从库后，最近几秒的写入不见了。</p><p><strong>原因</strong>：<strong>异步复制</strong>——主库写完就返回了，还没复制到从库就宕机 → 那些写入在从库上根本不存在。</p><p><strong>解法</strong>：</p><table tabindex="0"><thead><tr><th>方案</th><th>说明</th></tr></thead><tbody><tr><td><strong>半同步复制</strong></td><td>主库等至少一个从库 ACK → 丢数据窗口从&quot;不确定&quot;变成&quot;最多丢一点&quot;（但主库变慢）</td></tr><tr><td><strong>GTID + 选主时比对</strong></td><td>切主时检查各从库的复制位点，选丢失最少的</td></tr><tr><td><strong>强一致方案</strong></td><td>Group Replication / 同机房同步复制 / 分布式数据库</td></tr></tbody></table><p><strong>认知</strong>：<strong>主从是容灾 + 读扩展方案，不是数据零丢失方案</strong>。要求&quot;零丢失&quot;就得接受延迟和成本上升。</p><h3 id="_5-7-我们上了分布式数据库-——该追问什么" tabindex="-1">5.7 &quot;我们上了分布式数据库&quot;——该追问什么 <a class="header-anchor" href="#_5-7-我们上了分布式数据库-——该追问什么" aria-label="Permalink to &quot;5.7 &quot;我们上了分布式数据库&quot;——该追问什么&quot;">​</a></h3><p><strong>别急着接受这个说法</strong>。三个问题问过去就知道对方是真懂还是跟风：</p><table tabindex="0"><thead><tr><th>追问</th><th>想知道什么</th></tr></thead><tbody><tr><td><strong>&quot;强一致的写有多高的延迟？&quot;</strong></td><td>跨节点共识的开销。正常单库 1ms，分布式可能 5~50ms</td></tr><tr><td><strong>&quot;TiDB 集群谁来管？半夜挂了谁处理？&quot;</strong></td><td><strong>运维归属</strong>——这是最大的坑</td></tr><tr><td><strong>&quot;MySQL 语法完全兼容吗？哪些不兼容？&quot;</strong></td><td>迁移成本；DDL、索引、外键都有差异</td></tr></tbody></table><p><strong>如果对方答不上来</strong>，那大概率是&quot;业务方没真正用起来，只是接了个中间件&quot;。<strong>分布式数据库的价值是省掉分片设计的活，代价是运维复杂度上升</strong>——前提是团队真的有能力运维。</p><blockquote><p><strong>自检</strong>：一个团队说&quot;我们数据量大所以用了分库分表&quot;。你会追问哪三件事来确认这个决定是对的？</p></blockquote><details class="details custom-block"><summary>参考答案</summary><p>我会问三件事：</p><p><strong>① &quot;数据量到底多大？单表多少行？&quot;</strong> 分库分表的常见触发点是<strong>单表超过 1000 万行</strong>（索引深度变大、DDL 变慢、备份恢复变久）。如果实际只有几百万行，<strong>分片的复杂度（分布式 ID、跨片事务、跨片查询）完全不值得</strong>——加索引、优化 SQL、读写分离可能就够了。这一条最容易被跳过，因为&quot;数据量大&quot;是模糊的说法。</p><p><strong>② &quot;分了之后，这个列表接口的 SQL 还能带上分片键吗？&quot;</strong> 如果不能，<strong>每次列表查询都要跨片归并</strong> → 分片后反而更慢。分片键要和主要查询条件对齐，这是设计的第一原则。</p><p><strong>③ &quot;跨片事务现在怎么处理的？业务里还有哪些操作是跨片的？&quot;</strong> 如果答案含糊（比如&quot;用分布式事务框架&quot;），要追问<strong>用的是哪种方案、代码里怎么写的</strong>。跨片事务是分片后最大的复杂度来源，<strong>设计上应该尽量避免</strong>（通过分片键让 90% 操作落在单片内）。</p><p><strong>补充问一句</strong>：&quot;扩容过吗？扩容方案是什么？&quot;——回答&quot;没扩过&quot;或&quot;停机迁移&quot;都是可接受的答案，但如果对方从没想过，说明这个决定是&quot;跟风做的&quot;而不是&quot;算出来的&quot;。</p></details><hr><h2 id="_6-延伸" tabindex="-1">6. 延伸 <a class="header-anchor" href="#_6-延伸" aria-label="Permalink to &quot;6. 延伸&quot;">​</a></h2><blockquote><p>难度：了解</p></blockquote><h3 id="对照总结-学透这张表就够了" tabindex="-1">对照总结（学透这张表就够了） <a class="header-anchor" href="#对照总结-学透这张表就够了" aria-label="Permalink to &quot;对照总结（学透这张表就够了）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>数据形态</th><th>写一致靠</th><th>读扩展</th><th>写扩展</th><th>你要&quot;设计&quot;的</th></tr></thead><tbody><tr><td>① 多实例单库</td><td>一份</td><td><strong>DB 行锁</strong></td><td>加实例</td><td>加实例（受单库上限）</td><td>Redis 锁管代码互斥</td></tr><tr><td>② 主从</td><td>全量多副本</td><td>主库行锁 + <strong>复制策略</strong></td><td><strong>加从库</strong></td><td>❌（主库单点）</td><td>半同步 / 读写路由 / 延迟监控</td></tr><tr><td>③ 分片</td><td>各存部分</td><td>片内行锁 + 跨片事务</td><td>加片</td><td>加片</td><td><strong>分片键</strong> / 分布式 ID / 幂等</td></tr><tr><td>④ TiDB</td><td>切片 + 副本</td><td><strong>内部封装</strong></td><td>自动</td><td>自动</td><td>基本不用</td></tr></tbody></table><p><strong>贯穿主线一句话</strong>：<strong>能局部锁就别跨节点</strong>——单库靠 DB 行锁，主从靠复制策略（不是锁），分片靠分片键让锁局部化，分布式库靠底层封装。</p><h3 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to &quot;相关篇目&quot;">​</a></h3><table tabindex="0"><thead><tr><th>篇目</th><th>关系</th></tr></thead><tbody><tr><td><a href="/knowledge/service/common/concurrency-locks.html">并发锁应用</a></td><td>锁的粒度 / 阵营 / 具体 API</td></tr><tr><td><a href="/knowledge/service/common/distributed-basics.html">分布式基础</a></td><td>CAP、分布式事务、分布式 ID、一致性哈希</td></tr><tr><td><a href="/knowledge/service/common/mysql-advanced.html">MySQL 进阶</a></td><td>主从复制、索引、慢查询</td></tr><tr><td><a href="/knowledge/service/java/java-high-concurrency.html">Java 高并发与高可用设计</a></td><td>架构视角的容量与演进</td></tr><tr><td><a href="/knowledge/service/java/middleware.html">中间件全景与 Java 实战</a></td><td>Redis 分布式锁的边界</td></tr></tbody></table>`,146)])])}const u=s(d,[["render",r]]);export{c as __pageData,u as default};
